const CAM_KF = {
  hold: 4.45, out: 5.05,          // sit on the masthead, then pull the sheet back
  s0: 1.100, cy0: 430,            // close on the masthead
  s1: 1.000, cy1: 960,            // the whole page
  pushS: 1.018, pushCy: 988,      // the last, barely-there creep inward
  settle: 14.15,                  // movement is over; let the page be still
};

function camAt(t) {
  const K = CAM_KF;
  let s, cy;
  if (t <= K.hold) {
    const d = cl(t / K.hold);
    s  = K.s0 + 0.012 * d;              // the faintest drift while we wait
    cy = K.cy0;
  } else if (t <= K.hold + K.out) {
    const e3 = eInOut(cl((t - K.hold) / K.out));
    s  = (K.s0 + 0.012) + (K.s1 - K.s0 - 0.012) * e3;
    cy = K.cy0 + (K.cy1 - K.cy0) * e3;
  } else {
    const e3 = eInOut(cl((t - K.hold - K.out) / (K.settle - K.hold - K.out)));
    s  = K.s1 + (K.pushS - K.s1) * e3;
    cy = K.cy1 + (K.pushCy - K.cy1) * e3;
  }
  return { s, cx: 540, cy };
}

